$(document).ready(function(){
            $(".owl-carousel").owlCarousel({
                items: 3,
                margin: 30,
                loop: true,
                nav: true,
                dots: false,
                autoplay: true,
                autoplayTimeout: 3000,
                responsive: {
                    0: { items: 1 },
                    768: { items: 2 },
                    1200: { items: 3 }
                }
            });
        });